// id, название, группа, уровень, тип (reps — повторения, time — секунды, hold — удержания), базовая доза,
// side — на каждую сторону, equip — инвентарь, load — нагрузка по ключам, tags, cues — подсказки,
// hold — секунд в одном удержании, relax — отдых между удержаниями
const E = (id, name, group, level, type, base, opts = {}) => ({
  id, name, group, level, type, base,
  side: !!opts.side, equip: opts.equip || [], load: opts.load || {}, tags: opts.tags || [], cues: opts.cues || [],
  hold: opts.hold || 0, relax: opts.relax || 0
});

